const definitions = [
 ['count','Particles',5000,30000,1000], ['flowSpeed','Flow speed',.02,1,.01], ['turbulence','Flow turbulence',.1,4,.1], ['damping','Damping',.8,.999,.001], ['repulsion','Repulsion strength',.1,8,.1], ['obstacleRadius','Obstacle radius',0,1,.01], ['distribution','Spread recovery',0,.5,.01], ['threshold','Camera threshold',.01,.5,.01], ['backgroundAdapt','Background adaptation',.0001,.05,.0001], ['particleSize','Particle size',1,5,.1], ['trail','Trail amount',0,1,.01], ['cropLeft','Crop left',0,.45,.01], ['cropRight','Crop right',0,.45,.01], ['cropTop','Crop top',0,.45,.01], ['cropBottom','Crop bottom',0,.45,.01]
];
export function mountControls(settings, reset) { const panel = document.querySelector('#controls'); panel.innerHTML = '<h1>Particle Field</h1>'; for (const [key, label, min, max, step] of definitions) { const id = `set-${key}`; const row = document.createElement('div'); row.className = 'control'; row.innerHTML = `<label for="${id}">${label}</label><output>${settings[key]}</output><input id="${id}" type="range" min="${min}" max="${max}" step="${step}" value="${settings[key]}">`; const input = row.querySelector('input'), output = row.querySelector('output'); input.oninput = () => { settings[key] = +input.value; output.value = input.value; }; panel.append(row); }
 for (const [key,label] of [['invert','Invert black / white'],['flipX','Camera flip X'],['flipY','Camera flip Y']]) { const row = document.createElement('div'); row.className = 'control check'; row.innerHTML = `<label>${label}</label><input type="checkbox" ${settings[key] ? 'checked' : ''}>`; row.querySelector('input').onchange = e => settings[key] = e.target.checked; panel.append(row); }
 const hint = document.createElement('p'); hint.className = 'hint'; hint.textContent = 'H controls · D camera mask · F fullscreen · R relearn background'; panel.append(hint); return panel; }
